command -v python3>/dev/null||{ echo python3_required;exit 127;};python3 -c 'import sys,json,zlib,base64,math,time;A=sys.argv[1:];M=A[0]if A else"pack";N=int(A[1])if len(A)>1 else 16;I=int(A[2])if len(A)>2 else 0;C=int(A[3])if len(A)>3 else 0;eps=float(A[4])if len(A)>4 else 1e-6;ip=lambda x:x>1 and all(x%d for d in range(2,int(math.isqrt(x))+1));P=[];x=2;exec("while len(P)<max(N,64):\n if ip(x):P.append(x)\n x+=1");LG=lambda s:sum((b+1)*math.log(P[i])for i,b in enumerate(s.encode()));S,E=LG("Solution(s)"),LG("Everything");DE=abs((E+(S-E)*math.exp(-.12*240))-E);raw=sys.stdin.buffer.read();exec("z=zlib.compress(raw,9);b=base64.b64encode(z).decode();q=zlib.decompress(base64.b64decode(b));D=[]\nfor n,p in enumerate(P[:N],1):\n c=C if n==I and C else p\n if c-p:D.append([n,p,c,abs(c-p)])\nR=int(q==raw);RM=int(not D);PL=1;EI=int(DE<=eps);AD=int(R and RM);ES=int(R and EI and RM);ZE=int(PL and EI and AD and ES);print(json.dumps({\"P\":\"CLZeroPack/BLEEM/RM/NO_SHA/Lossless/1\",\"Mode\":\"pack\",\"B\":len(raw),\"ZB\":len(z),\"B64B\":len(b),\"Codec\":\"zlib9+base64\",\"Payload\":b,\"BLEEM\":\"P^L+E^I+A^D+E^S\",\"P_L\":PL,\"E_I\":EI,\"A_D\":AD,\"E_S\":ES,\"DE\":DE,\"RM\":RM,\"D\":D[:3],\"ZE_info\":ZE,\"SCL_Formal\":ZE,\"LosslessReplay\":R,\"HashFunctionUsed\":False,\"PhysicalCosmicLaw\":False,\"RHProof\":False,\"Boundary\":\"lossless formal information-zero-entropy carrier\",\"UTC\":time.strftime(\"%Y-%m-%dT%H:%M:%SZ\",time.gmtime())},separators=(\",\",\":\")))"if M[0]=="p"else"o=json.loads(raw.decode());sys.stdout.buffer.write(zlib.decompress(base64.b64decode(o[\"Payload\"])))")' "$@"
